using System.IO.Compression;

namespace Crosio.Windows.Translation;

internal static class OfficialTranslationModelEmbeddedArtifacts
{
    public const string CreativeCommonsBy40License = "license.cc-by-4.0";
    public const string Apache20License = "license.apache-2.0";

    public static bool Contains(string resourceId) =>
        string.Equals(resourceId, CreativeCommonsBy40License, StringComparison.Ordinal) ||
        string.Equals(resourceId, Apache20License, StringComparison.Ordinal);

    public static Stream OpenRead(string resourceId)
    {
        var compressedBase64 = resourceId switch
        {
            CreativeCommonsBy40License => CreativeCommonsBy40LicenseGzipBase64,
            Apache20License => Apache20LicenseGzipBase64,
            _ => throw new TranslationModelInvalidException(
                $"未知的官方模型内置资源：{resourceId}"),
        };
        var compressed = Convert.FromBase64String(compressedBase64);
        return new GZipStream(
            new MemoryStream(compressed, writable: false),
            CompressionMode.Decompress);
    }

    // Exact, gzip-compressed bytes fetched from the canonical license publishers.
    // The uncompressed length and SHA-256 remain pinned by each model artifact.
    private const string CreativeCommonsBy40LicenseGzipBase64 = """
    
    """;

    private const string Apache20LicenseGzipBase64 = """
    
    """;
}
